{
  "passageId": "blockchain-features",
  "items": [
    {
      "id": "R1",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "블록체인 기술의 기본 설명에 새 블록의 처리 절차를 덧붙여 같은 기술의 작동 방식을 구체화한다."
    },
    {
      "id": "R2",
      "type": "PROCESS",
      "otherName": "",
      "reason": "새 블록의 전파와 검증 다음에 연결 여부를 결정하는 승인이 이어지는 단계적 순서이다."
    },
    {
      "id": "R3",
      "type": "PROCESS",
      "otherName": "",
      "reason": "승인 절차가 끝난 뒤 블록의 연결과 저장이 이루어지는 처리 순서를 나타낸다."
    },
    {
      "id": "R4",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "작업증명은 승인 과정에 쓰이는 합의 알고리즘의 구체적인 사례이다."
    },
    {
      "id": "R5",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "데이터 저장 속도라는 성능의 뜻을 단위 시간당 저장량이라는 계산식으로 나타낸다."
    },
    {
      "id": "R6",
      "type": "CAUSE",
      "otherName": "",
      "reason": "합의 알고리즘이 빠르게 작동하면 승인에 소요되는 시간이 짧아지는 실제 작용 관계이다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "승인 시간이 짧다는 사실을 데이터 저장 속도라는 성능의 정의와 연결하여 성능이 높다는 판단을 도출한다."
    },
    {
      "id": "R8",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "승인에 합의 알고리즘을 사용한다는 작동 설명에서 블록체인 유형에 따른 알고리즘 속도 차이로 논의가 옮겨 간다."
    },
    {
      "id": "R9",
      "type": "PROCESS",
      "otherName": "",
      "reason": "데이터 변경으로 연결이 끊어진 뒤 재연결을 위해 승인 단계를 거쳐야 한다는 절차적 순서를 보여 준다."
    },
    {
      "id": "R10",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "끊어진 모든 블록의 재연결에 승인이 필요하다는 사실이 연결 복구가 어렵다는 판단의 근거이다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "변경 후 연결 복구가 어렵다는 사실로부터 연결을 유지하면서 데이터를 변경하기 어렵다는 설명이 도출된다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "데이터 변경이 어렵다는 사실을 무결성의 정의에 비추어 무결성이 높다는 판단의 근거로 삼는다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "원래 데이터의 복원에는 승인이 필요하지 않다는 사실이 복원이 용이하다는 판단을 뒷받침한다."
    },
    {
      "id": "R14",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "무단 변경 후의 연결 복구와 삭제된 원래 데이터의 복원을 승인 필요 여부와 복구 난이도라는 같은 기준에서 비교한다."
    },
    {
      "id": "R15",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "블록을 연결하려면 승인이 필요하다는 일반 절차를 변경으로 연결이 끊어진 블록의 재연결에 적용한다."
    },
    {
      "id": "R16",
      "type": "CLASSIFICATION",
      "otherName": "",
      "reason": "무결성으로 정의한 무단 변경의 어려움이 보안성을 구성하는 한 성질로 포함된다."
    },
    {
      "id": "R17",
      "type": "CAUSE",
      "otherName": "",
      "reason": "동일 내용의 이중 포함을 검증하는 작동이 블록 간 이중 포함을 어렵게 만드는 관계이다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "모든 노드가 승인에 참여하는 작동 방식이 탈중앙성의 다수 노드 참여라는 성질을 구체적으로 보여 준다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "승인 시간이 짧아지는 것이 보안성 저하로 이어지는 실제 작용을 연결한다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "노드 증가가 성능 저하를 일으킨다는 사실을 바탕으로 높은 확장성이 성능 저하가 크지 않음을 뜻한다고 설명한다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "노드 제한으로 성능 저하를 막을 수 있다는 사실이 확장성 확보에 그 방법을 사용하는 이유를 뒷받침한다."
    },
    {
      "id": "R22",
      "type": "CAUSE",
      "otherName": "",
      "reason": "확장성을 확보하려고 노드 수를 제한하면 보안성이 낮아지는 상충 관계이다."
    },
    {
      "id": "R23",
      "type": "CAUSE",
      "otherName": "",
      "reason": "확장성을 확보하려고 노드 수를 제한하면 탈중앙성이 낮아지는 상충 관계이다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "비공개형의 노드 수 제한은 확장성 확보에 사용되는 노드 제한 방법의 구체적인 사례이다."
    },
    {
      "id": "R25",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 정의한 성능 개념을 확장성이라는 다른 특성을 설명하고 판정하는 기준으로 가져다 쓴다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "세 특성을 함께 높일 방법이 없다는 기술적 한계가 대규모 채택을 가로막는 원인으로 제시된다."
    }
  ]
}

